// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address caller, uint256 id, bytes calldata data) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.onERC721Received(address(0), address(0), id, data) returns (bytes4 selector) {
            assertTrue(selector == bytes4(0x150b7a02));
        } catch {
            assertTrue(false);
        }
    }
}
